(function() {
    'use strict';

    class OrganigramaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Organigrama';
            this.version = '1.1.0';
            this.ROUNDS = [
                { panelId: 'round1Controls', descKey: 'r1_desc' },
                { panelId: 'round2Controls', descKey: 'r2_desc' },
                { panelId: 'round3Controls', descKey: 'r3_desc' },
                { panelId: 'round4Controls', descKey: 'r4_desc' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    ebitdaMargin: 4.4,
                    decisionSpeed: 21,
                    consistency: 30,
                    revenue: 180000000,
                    scoreHistory: [],
                    marginHistory: [],
                    speedHistory: [],
                    consistencyHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    estimatedSpan: 50,
                    primaryProblem: 'authority_confusion'
                };
            }
            this._updateBriefing(state);

            // Keep the decision panel in sync when the learner uses "Undo Last Round".
            // Runs after the framework's own undo handler via setTimeout(0).
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn && !undoBtn._orgUndoBound) {
                undoBtn._orgUndoBound = true;
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        if (window.mySimulation) self._updateBriefing(window.mySimulation.state);
                    }, 0);
                });
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                try {
                    briefEl.innerHTML = window.mySimulation.t(round.descKey);
                } catch(e) {
                    briefEl.innerHTML = '';
                }
            }
            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod;
            var t = function(k) { return window.mySimulation.t(k); };
            var warn = function(k) { window.mySimulation.uiManager.showNotification(t(k), 'warning'); return false; };
            var num = function(id) { var el = document.getElementById(id); return el ? parseInt(el.value, 10) : NaN; };
            var sel = function(id) { var el = document.getElementById(id); return el ? el.value : ''; };

            if (period === 1) {
                decisions.estimatedSpan = num('estimatedSpanInput');
                decisions.primaryProblem = sel('primaryProblemSelect');
                if (!Number.isFinite(decisions.estimatedSpan) || decisions.estimatedSpan < 5 || decisions.estimatedSpan > 200) return warn('span_warning');
                if (!decisions.primaryProblem) return warn('choose_warning');
            } else if (period === 2) {
                decisions.structureType = sel('structureTypeSelect');
                decisions.numVPRoles = num('numVPInput');
                decisions.managementLayers = num('layersInput');
                if (!decisions.structureType) return warn('choose_warning');
                if (!Number.isFinite(decisions.numVPRoles) || decisions.numVPRoles < 2 || decisions.numVPRoles > 6) return warn('structure_warning');
                if (!Number.isFinite(decisions.managementLayers) || decisions.managementLayers < 2 || decisions.managementLayers > 6) return warn('structure_warning');
            } else if (period === 3) {
                decisions.discountAuthority = sel('discountAuthoritySelect');
                decisions.delegationThreshold = num('delegationInput');
                decisions.inventoryAuthority = sel('inventoryAuthoritySelect');
                if (!decisions.discountAuthority || !decisions.inventoryAuthority) return warn('choose_warning');
                if (!Number.isFinite(decisions.delegationThreshold) || decisions.delegationThreshold < 0 || decisions.delegationThreshold > 10) return warn('raci_warning');
            } else if (period === 4) {
                decisions.timelineMonths = num('timelineInput');
                decisions.reorgBudget = num('budgetInput');
                decisions.changeApproach = sel('changeApproachSelect');
                if (!decisions.changeApproach) return warn('choose_warning');
                if (!Number.isFinite(decisions.timelineMonths) || decisions.timelineMonths < 1 || decisions.timelineMonths > 18) return warn('impl_warning');
                if (!Number.isFinite(decisions.reorgBudget) || decisions.reorgBudget < 50000 || decisions.reorgBudget > 2000000) return warn('budget_warning');
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundScore = 0;
            var roundName = '';

            if (period === 1) {
                roundName = window.mySimulation.t('r1_short');
                var spanDiff = Math.abs((d.estimatedSpan || 50) - 100);
                var spanPts = spanDiff <= 20 ? 10 : spanDiff <= 40 ? 7 : spanDiff <= 60 ? 4 : 2;
                var probMap = {
                    authority_confusion: 15,
                    excessive_span: 12,
                    slow_decisions: 10,
                    lack_specialization: 8,
                    financial_fragmentation: 5
                };
                var probPts = probMap[d.primaryProblem] || 5;
                roundScore = spanPts + probPts;

            } else if (period === 2) {
                roundName = window.mySimulation.t('r2_short');
                var structMap = { functional: 14, hybrid: 10, matrix: 5, divisional: 2 };
                var structPts = structMap[d.structureType] || 5;
                var vpCount = d.numVPRoles || 3;
                var vpPts = (vpCount >= 3 && vpCount <= 4) ? 6 : (vpCount === 2 || vpCount === 5) ? 3 : 1;
                var layers = d.managementLayers || 3;
                var layPts = (layers >= 3 && layers <= 4) ? 5 : layers === 2 ? 3 : 2;
                roundScore = structPts + vpPts + layPts;

                var r2 = roundScore / 25;
                ds.ebitdaMargin += 0.5 * r2;
                ds.decisionSpeed -= Math.round(6 * r2);
                ds.consistency += Math.round(25 * r2);

            } else if (period === 3) {
                roundName = window.mySimulation.t('r3_short');
                var discMap = { vp_sales: 10, cfo: 7, ceo: 4, regional_manager: 2 };
                var discPts = discMap[d.discountAuthority] || 5;
                var delThresh = d.delegationThreshold || 2;
                var delPts = (delThresh >= 2 && delThresh <= 3) ? 8 : (delThresh >= 1 && delThresh <= 5) ? 5 : 2;
                var invMap = { vp_logistics: 7, vp_operations: 5, cfo: 3, regional_manager: 2 };
                var invPts = invMap[d.inventoryAuthority] || 3;
                roundScore = discPts + delPts + invPts;

                var r3 = roundScore / 25;
                ds.ebitdaMargin += 0.3 * r3;
                ds.decisionSpeed -= Math.round(8 * r3);
                ds.consistency += Math.round(25 * r3);

            } else if (period === 4) {
                roundName = window.mySimulation.t('r4_short');
                var months = d.timelineMonths || 6;
                var timePts = (months >= 5 && months <= 7) ? 9 : (months >= 3 && months <= 4) ? 7 : (months >= 8 && months <= 10) ? 5 : 3;
                var budget = d.reorgBudget || 450000;
                var budPts = (budget >= 350000 && budget <= 600000) ? 8 : (budget >= 200000 && budget <= 800000) ? 5 : 2;
                var chgMap = { phased_pilot: 8, gradual: 5, big_bang: 3 };
                var chgPts = chgMap[d.changeApproach] || 3;
                roundScore = timePts + budPts + chgPts;

                var r4 = roundScore / 25;
                ds.ebitdaMargin += 0.3 * r4;
                ds.decisionSpeed -= Math.round(4 * r4);
                ds.consistency += Math.round(15 * r4);
            }

            ds.ebitdaMargin = Math.min(Math.round(ds.ebitdaMargin * 10) / 10, 6.5);
            ds.decisionSpeed = Math.max(ds.decisionSpeed, 3);
            ds.consistency = Math.min(ds.consistency, 98);

            ds.totalScore += roundScore;
            ds.scoreHistory.push(roundScore);
            ds.marginHistory.push(ds.ebitdaMargin);
            ds.speedHistory.push(ds.decisionSpeed);
            ds.consistencyHistory.push(ds.consistency);

            // Advance the briefing + decision panel to the NEXT round using the local `period`
            // (the round just scored). Reading state.currentPeriod here is off-by-one because the
            // framework increments it immediately after calculateResults() returns, which made the
            // panel jump a round ahead of the counter (R1 submit -> showed R3, etc.).
            this._updateBriefing({ currentPeriod: period + 1 });

            return {
                period: state.currentPeriod,
                roundName: roundName,
                roundScore: roundScore,
                ebitdaMargin: ds.ebitdaMargin,
                decisionSpeed: ds.decisionSpeed,
                consistency: ds.consistency,
                totalScore: ds.totalScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore');
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaMargin',
                (v) => v.toFixed(1) + '%');
            uiManager.bind('speedDisplay', 'domainState.decisionSpeed',
                (v) => v + ' days');
            uiManager.bind('consistencyDisplay', 'domainState.consistency',
                (v) => v + '%');
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: window.mySimulation.t('chart_ds_label'),
                            data: [],
                            backgroundColor: ['#1a2744', '#2c5282', '#276749', '#c05621'],
                            borderColor: ['#1a2744', '#2c5282', '#276749', '#c05621'],
                            borderWidth: 1,
                            borderRadius: 3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: window.mySimulation.t('chart_title'), font: { size: 14, weight: '600' } },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 25, ticks: { stepSize: 5 } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = [];
            var keys = ['r1_short', 'r2_short', 'r3_short', 'r4_short'];
            for (var i = 0; i < state.domainState.scoreHistory.length; i++) {
                try {
                    labels.push(window.mySimulation.t(keys[i]));
                } catch(e) {
                    labels.push('R' + (i + 1));
                }
            }
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = history.reduce(function(s, r) {
                return s + (r.results ? r.results.roundScore : 0);
            }, 0);
            var lastEntry = history[history.length - 1];
            var finalMargin = lastEntry && lastEntry.results ? lastEntry.results.ebitdaMargin : 4.4;
            var finalSpeed = lastEntry && lastEntry.results ? lastEntry.results.decisionSpeed : 21;
            var finalConsistency = lastEntry && lastEntry.results ? lastEntry.results.consistency : 30;

            var t = function(k, p) { return window.mySimulation.t(k, p); };
            var performance, tierInsight;
            if (totalScore >= 75) { performance = t('perf_excellent'); tierInsight = t('insight_excellent'); }
            else if (totalScore >= 55) { performance = t('perf_good'); tierInsight = t('insight_good'); }
            else if (totalScore >= 35) { performance = t('perf_developing'); tierInsight = t('insight_developing'); }
            else { performance = t('perf_needs'); tierInsight = t('insight_needs'); }

            var insights = [tierInsight];
            if (finalMargin >= 5.5) insights.push(t('insight_margin', { v: finalMargin.toFixed(1) }));
            if (finalSpeed <= 5) insights.push(t('insight_speed', { v: finalSpeed }));
            if (finalConsistency >= 90) insights.push(t('insight_consistency', { v: finalConsistency }));

            return {
                totalScore: totalScore,
                finalMargin: finalMargin,
                finalSpeed: finalSpeed,
                finalConsistency: finalConsistency,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.roundScore >= 20) return window.mySimulation.t('hint_high');
            if (results.roundScore >= 12) return window.mySimulation.t('hint_medium');
            return window.mySimulation.t('hint_low');
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundName', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score' },
                { key: 'results.ebitdaMargin', label: 'EBITDA %', i18nKey: 'col_ebitda', formatter: (v) => v.toFixed(1) + '%' },
                { key: 'results.decisionSpeed', label: 'Speed (days)', i18nKey: 'col_speed' },
                { key: 'results.consistency', label: 'Consistency', i18nKey: 'col_consistency', formatter: (v) => v + '%' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:               `El Organigrama`,
                    subtitle:            `Distribuidora Nacional S.A. — Structure, Authority & Decision-Making`,
                    header_badge:        `ORGANIZATIONAL REDESIGN`,
                    round_label:         `Round`,
                    period_of:           `of`,
                    score_label:         `Total Score`,
                    score_sub:           `/ 100 points`,
                    ebitda_label:        `EBITDA Margin`,
                    ebitda_target:       `Target: 5.5%+`,
                    speed_label:         `Decision Speed`,
                    speed_target:        `Target: 3–5 days`,
                    consistency_label:   `Consistency`,
                    consistency_target:  `Target: 90%+`,
                    briefing_title:      `Situation Briefing`,
                    decisions_heading:   `Your Decisions`,
                    span_label:          `Estimated Average Span of Control`,
                    span_hint:           `Estimate DN's CURRENT average span (each director carries 50–150 reports). The healthy target is 6–10 — that gap is the problem you're diagnosing.`,
                    problem_label:       `Primary Structural Problem`,
                    structure_label:     `Proposed Structure Type`,
                    vp_label:            `VP-Level Roles to Create`,
                    layers_label:        `Management Layers (CEO to front-line)`,
                    discount_auth_label: `Authority for Discounts Over 5%`,
                    delegation_label:    `Local Discount Approval Limit (%)`,
                    inventory_auth_label:`Inventory Allocation Authority`,
                    timeline_label:      `Full Rollout Timeline (months)`,
                    budget_label:        `Reorganization Budget (USD)`,
                    change_label:        `Change Management Approach`,
                    submit_btn:          `Submit Round`,
                    undo_btn:            `Undo Last Round`,
                    span_warning:        `Span of control estimate must be between 5 and 200`,
                    structure_warning:   `Please select valid values for all structure fields`,
                    raci_warning:        `Delegation threshold must be between 0% and 10%`,
                    impl_warning:        `Timeline must be between 1 and 18 months`,
                    r1_short:            `Diagnostic`,
                    r2_short:            `Design`,
                    r3_short:            `Governance`,
                    r4_short:            `Implementation`,
                    r1_desc:             `Distribuidora Nacional just lost its largest client, Grupo Retail Centroamericano ($12M annual revenue), because three regional directors gave conflicting responses to a 5% discount request.<br><br>The company has 500 employees across 3 regions (Tegucigalpa: 50, SPS: 150, El Salvador: 120, plus 180 unassigned). Each region is run by a director with 50–150 direct reports and no VP-level specialization. Finance, sales, logistics, and operations are all handled independently per region.<br><br><strong>Your task:</strong> Diagnose the structural problems. Estimate the actual average span of control and identify the root cause of the GRC failure.`,
                    r2_desc:             `Based on your diagnosis, design a new organizational structure for DN. Consider four approaches:<br><br><strong>Functional:</strong> Organized by expertise (VP Sales, VP Logistics, VP Ops) — clear specialization, consistent decisions across regions.<br><strong>Divisional:</strong> Organized by geography (EVP per region) — local autonomy but costly duplication and the approach that already failed.<br><strong>Matrix:</strong> Dual reporting lines — flexible but complex, better suited for tech companies.<br><strong>Hybrid:</strong> Functional VPs plus lightweight regional coordinators — balanced but adds moderate complexity.<br><br>Define how many VP roles DN needs and the appropriate number of management layers for a 500-employee distribution company (optimal: 3–4 layers).`,
